import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

// 1. DOMAIN LAYER: Pure Entity
class BankAccount {
    private final String id;
    private double balance;

    public BankAccount(String id, double initialBalance) {
        this.id = id;
        this.balance = initialBalance;
    }
    public String getId() { return id; }
    public double getBalance() { return balance; }
    public boolean debit(double amt) {
        if (amt <= 0 || amt > balance) return false;
        balance -= amt;
        return true;
    }
    public void credit(double amt) {
        if (amt > 0) balance += amt;
    }
}

// 2. REPOSITORY LAYER: Data Abstraction
interface AccountRepository {
    void save(BankAccount account);
    Optional<BankAccount> findById(String id);
}

class InMemoryAccountRepository implements AccountRepository {
    private final Map<String, BankAccount> store = new HashMap<>();
    @Override
    public void save(BankAccount account) { store.put(account.getId(), account); }
    @Override
    public Optional<BankAccount> findById(String id) { return Optional.ofNullable(store.get(id)); }
}

// 3. SERVICE LAYER: Business Orchestrator
class TransferService {
    private final AccountRepository repo;
    public TransferService(AccountRepository repo) { this.repo = repo; }

    public boolean transferFunds(String fromId, String toId, double amount) {
        Optional<BankAccount> sourceOpt = repo.findById(fromId);
        Optional<BankAccount> targetOpt = repo.findById(toId);
        if (sourceOpt.isEmpty() || targetOpt.isEmpty()) return false;

        BankAccount source = sourceOpt.get();
        BankAccount target = targetOpt.get();
        if (!source.debit(amount)) return false;
        target.credit(amount);
        return true;
    }
}

// 4. PRESENTATION LAYER & COMPOSITION ROOT
public class LayeredBankApp {
    public static void main(String[] args) {
        // Composition Root: Wiring dependencies
        AccountRepository repo = new InMemoryAccountRepository();
        repo.save(new BankAccount("ACC-1", 500.0));
        repo.save(new BankAccount("ACC-2", 200.0));

        TransferService transferService = new TransferService(repo);
        boolean success = transferService.transferFunds("ACC-1", "ACC-2", 150.0);

        System.out.println("Transfer Success: " + success);
        System.out.println("ACC-1: $" + repo.findById("ACC-1").get().getBalance());
        System.out.println("ACC-2: $" + repo.findById("ACC-2").get().getBalance());
    }
}

