import java.util.ArrayList;
import java.util.List;

// Custom Domain Exception
class InsufficientInventoryException extends Exception {
    public InsufficientInventoryException(String msg) { super(msg); }
}

// Domain Observer / Event Listener
interface OrderEventListener {
    void onOrderPlaced(String orderId, double amount);
}

class AuditLogListener implements OrderEventListener {
    @Override
    public void onOrderPlaced(String orderId, double amount) {
        System.out.println("[AUDIT LOG] Order created: " + orderId + " for $" + amount);
    }
}

class InventoryService {
    private int stock = 5;
    public void deduct(int count) throws InsufficientInventoryException {
        if (count > stock) {
            throw new InsufficientInventoryException("Requested: " + count + ", Available: " + stock);
        }
        stock -= count;
    }
}

class OrderService {
    private final InventoryService inventory;
    private final List<OrderEventListener> listeners = new ArrayList<>();

    public OrderService(InventoryService inv) { this.inventory = inv; }
    public void addListener(OrderEventListener l) { listeners.add(l); }

    public void placeOrder(String orderId, int qty, double price) {
        try {
            inventory.deduct(qty);
            for (OrderEventListener l : listeners) {
                l.onOrderPlaced(orderId, qty * price);
            }
            System.out.println("Order processed successfully.");
        } catch (InsufficientInventoryException e) {
            System.out.println("Order Failed: " + e.getMessage());
        }
    }
}

public class DomainEventsDemo {
    public static void main(String[] args) {
        InventoryService inv = new InventoryService();
        OrderService orderSvc = new OrderService(inv);
        orderSvc.addListener(new AuditLogListener());

        orderSvc.placeOrder("ORD-101", 2, 50.0);
        orderSvc.placeOrder("ORD-102", 10, 50.0); // Triggers domain exception!
    }
}

