import java.util.ArrayList;
import java.util.List;

class DuplicateUsernameException extends Exception {
    public DuplicateUsernameException(String message) {
        super(message);
    }
}

class RegistrationService {
    private final List<String> registered = new ArrayList<>();

    public void register(String username) throws DuplicateUsernameException {
        if (registered.contains(username)) {
            throw new DuplicateUsernameException("Username '" + username + "' is already taken");
        }
        registered.add(username);
        System.out.println("Registered: " + username);
    }
}

public class DomainExceptionApp {
    public static void main(String[] args) {
        RegistrationService service = new RegistrationService();
        try {
            service.register("munaf085");
            service.register("munaf085");
        } catch (DuplicateUsernameException e) {
            System.out.println("Caught: " + e.getMessage());
        }
    }
}

import java.util.ArrayList;
import java.util.List;

interface DomainEventListener {
    void onEvent(String topic, String payload);
}

class ConsoleAuditListener implements DomainEventListener {
    @Override
    public void onEvent(String topic, String payload) {
        System.out.println("[AUDIT] " + topic + ": " + payload);
    }
}

class EventPublisher {
    private final List<DomainEventListener> listeners = new ArrayList<>();

    public void subscribe(DomainEventListener l) {
        listeners.add(l);
    }

    public void publish(String topic, String payload) {
        for (DomainEventListener l : listeners) {
            l.onEvent(topic, payload);
        }
    }
}

public class DomainEventsApp {
    public static void main(String[] args) {
        EventPublisher publisher = new EventPublisher();
        publisher.subscribe(new ConsoleAuditListener());
        publisher.publish("USER_LOGIN", "User munaf logged in from 192.168.1.1");
    }
}

