import java.util.HashMap;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.Optional;

class Product {
    private String id;
    private double price;
    public Product(String id, double p) { this.id = id; this.price = p; }
    public String getId() { return id; }
    public double getPrice() { return price; }
}

class ProductRepository {
    private Map<String, Product> db = new HashMap<>();
    public void add(Product p) { db.put(p.getId(), p); }
    public Optional<Product> find(String id) {
        return Optional.ofNullable(db.get(id));
    }
}

class ProductService {
    private final ProductRepository repo;
    public ProductService(ProductRepository repo) { this.repo = repo; }
    public double getPrice(String id) {
        return repo.find(id)
                .map(Product::getPrice)
                .orElseThrow(() -> new NoSuchElementException("Product not found: " + id));
    }
}

public class NpeBugDemo {
    public static void main(String[] args) {
        ProductRepository repo = new ProductRepository();
        ProductService service = new ProductService(repo);
        try {
            service.getPrice("PROD-999");
        } catch (NoSuchElementException e) {
            System.out.println("Caught: " + e.getMessage());
        }
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

class OrderEntity {
    private final String id;
    private final double amount;
    private String status;

    public OrderEntity(String id, double amount) {
        this.id = id;
        this.amount = amount;
        this.status = "PENDING";
    }
    public void markPaid() { this.status = "PAID"; }
    public String getId() { return id; }
    public double getAmount() { return amount; }
    public String getStatus() { return status; }
}

interface OrderRepo {
    void save(OrderEntity o);
    Optional<OrderEntity> find(String id);
}

class InMemoryOrderRepo implements OrderRepo {
    private final Map<String, OrderEntity> map = new HashMap<>();
    @Override
    public void save(OrderEntity o) { map.put(o.getId(), o); }
    @Override
    public Optional<OrderEntity> find(String id) { return Optional.ofNullable(map.get(id)); }
}

class FulfillmentService {
    private final OrderRepo repo;
    public FulfillmentService(OrderRepo repo) { this.repo = repo; }

    public boolean processPayment(String id) {
        Optional<OrderEntity> opt = repo.find(id);
        if (opt.isEmpty()) return false;
        OrderEntity o = opt.get();
        o.markPaid();
        repo.save(o);
        return true;
    }
}

public class MultiTierApp {
    public static void main(String[] args) {
        OrderRepo repo = new InMemoryOrderRepo();
        repo.save(new OrderEntity("ORD-1", 250.0));

        FulfillmentService service = new FulfillmentService(repo);
        service.processPayment("ORD-1");

        System.out.println("Order ORD-1 status: " + repo.find("ORD-1").get().getStatus());
    }
}
